    const filter=el('license-lot-filter'),old=filter.value;filter.innerHTML='<option value="">Todos los lotes</option>'+state.lots.map(l=>'<option value="'+h(l.id)+'">'+h(l.name||l.courseName||l.id)+'</option>').join('');filter.value=old;
