  function mailResultMessage(result) {
    if(result?.status==='accepted')return 'Correo aceptado por el proveedor. Esto no confirma la entrega en la bandeja del comprador.';
    if(result?.status==='queued')return 'Correo preparado para envío. Puedes consultar su estado en Integraciones.';
    if(result?.status==='sending')return 'El envío está en curso. Puedes consultar su estado en Integraciones.';
    const errors={failed:'El envío anterior falló. Revisa el historial de correos antes de volver a intentarlo.',cancelled:'El envío está cancelado. Revisa la licencia y el historial antes de volver a intentarlo.',manual_review:'El envío requiere revisión. Su entrega no está confirmada; consulta el historial de correos.'};
    throw new Error(errors[result?.status]||'No se pudo confirmar el estado del correo. Revisa el historial antes de repetir el envío.');
  }
  function isManualFallbackError(error) {
    return error?.code === 'MAIL_NOT_CONFIGURED' || error?.code === 'MAIL_RETRY_REQUIRED' || error?.code === 'LICENSE_SERIAL_UNAVAILABLE'
      || error?.code === 'CUSTOMER_EMAIL_REQUIRED' || error?.code === 'LICENSE_EXPIRED' || error?.code === 'MAIL_ERROR' || error?.status === 503;
  }
  async function openManualLicenseDialog(license) {
    const data = await req('GET', '/licenses/' + encodeURIComponent(license.id) + '/key');
    showDialog('Clave para envío manual',
      '<p class="muted">Comparte esta clave por el canal que prefieras (correo personal, WhatsApp o chat seguro).</p>'
      + field('manualLicenseKey', 'Clave de acceso', data.key, 'textarea', { readonly: true, wide: true }) +
      '<div id="manual-license-actions" class="actions"></div>', null);
    el('manual-license-actions').append(button('Copiar clave', async () => {
      await navigator.clipboard.writeText(data.key);
      el('workspace-dialog-msg').textContent = 'Clave copiada.';
    }));
  }
  function emailLicense(license) {
    showDialog('Enviar acceso por correo','<p>Se solicitará el envío de la clave a <strong>'+h(license.customerEmail||'el comprador')+'</strong>.</p>',async()=>{
      try {
        const result=await req('POST','/licenses/'+encodeURIComponent(license.id)+'/email',{});
        const outcome=mailResultMessage(result);
        showDialog('Estado del correo','<p>'+h(outcome)+'</p>',null);
        return false;
      } catch (error) {
        if (isManualFallbackError(error)) {
          showDialog('El envío por correo no se pudo completar',
            '<p class="notice">No se pudo enviar por correo automáticamente, así que la entrega manual queda habilitada.</p><p>Clave del comprador:</p>', null);
          await openManualLicenseDialog(license);
          return false;
        }
        throw error;
      }
    },'Preparar envío');
  }
