  async function customers(page=1){const data=await req('GET','/customers'+qs({q:el('customer-search').value.trim(),page,pageSize:30}));state.customers=data.customers||[];state.customerPage=data.page||page;const area=el('workspace-customers');area.innerHTML=state.customers.length?table(['Comprador','Contacto','Licencias','Última actividad','Acciones'],state.customers.map((c,i)=>'<tr><td><strong>'+h(c.name||c.email)+'</strong><div class="muted">'+h(c.name?c.email:'')+'</div></td><td>'+h(c.phone||'—')+'</td><td>'+number(c.activeLicenses)+' activas / '+number(c.totalLicenses)+' total</td><td>'+h(date(c.lastActivity))+'</td><td id="customer-actions-'+i+'"></td></tr>').join('')):empty('No hay compradores en esta búsqueda','Aparecerán cuando tus licencias tengan un comprador asignado.');state.customers.forEach((c,i)=>fillActions(el('customer-actions-'+i),[button('Editar ficha',()=>editCustomer(c)),button('Ver licencias',async()=>{el('up-course').value='';await selectCourse();el('license-search').value=c.email;await navigate('licencias');await loadLicenseItems(1);})]));const pagination=document.createElement('div');pagination.className='pagination';pagination.append(button('Anterior',()=>customers(state.customerPage-1),{disabled:state.customerPage<=1}));const text=document.createElement('span');text.className='muted';text.textContent='Página '+state.customerPage+' · '+number(data.total)+' compradores';pagination.append(text,button('Siguiente',()=>customers(state.customerPage+1),{disabled:state.customerPage*(data.pageSize||30)>=(data.total||0)}));area.append(pagination);}
